def normalize(relative, source):
    if relative=='src/game/remove_diagnostics.cpp' and 'BindingDetails {Identity,Refund,BuildingTargets}' in source:
        building_target_delta=[('enum class BindingDetails {Identity,Refund,BuildingTargets};', 'enum class BindingDetails {Identity,Refund};'), ('    json retained=json::array();bool retained_present=false;\n    for(auto& [id,saved]:registry) {', '    json retained=json::array();\n    for(auto& [id,saved]:registry) {'), ('        if(saved.generation!=registry_generation||saved.world!=actual||saved.snapshot!=session_snapshot||saved.scene_owner=="retired")continue;\n        retained_present=true;\n', '        if(saved.generation!=registry_generation||saved.world!=actual||saved.snapshot!=session_snapshot||saved.scene_owner=="retired")continue;\n'), ('        if(details==BindingDetails::BuildingTargets&&omit_metadata&&omit_metadata->contains(saved.uid)&&!saved.revoked&&!saved.unknown){\n            // The Building census already excludes this admitted saved Scenery.\n            // Preserve the stored field guards without allocating its unused row.\n            for(const char* field:{"type","variant","x","y","z"})(void)saved.metadata.at(field);\n            if(saved.metadata.contains("rotation"))(void)saved.metadata.at("rotation");\n            if(saved.metadata.contains("scale"))(void)saved.metadata.at("scale");\n            continue;\n        }\n        retained.push_back({{"snapshot_id",saved.snapshot},{"record_key",saved.key},{"local_uid",saved.uid},', '        retained.push_back({{"snapshot_id",saved.snapshot},{"record_key",saved.key},{"local_uid",saved.uid},'), ('    if(retained_present) {\n', '    if(!retained.empty()) {\n')]
        for added,prior in building_target_delta:
            assert source.count(added)==1, 'Building target row suppression changed its exact source boundary'
            source=source.replace(added,prior,1)
    if relative=='src/game/remove_diagnostics.cpp':
        owner_delta=(
            ('BindingDetails details,const std::set<uint64_t>* omit_metadata=nullptr)', 'BindingDetails details)'),
            ('if(!saved.revoked&&!saved.unknown&&(!omit_metadata||!omit_metadata->contains(saved.uid))) {', 'if(!saved.revoked&&!saved.unknown) {'),
            ('collect_bindings_body(pending,error,details,omit_metadata)', 'collect_bindings_body(pending,error,details)'),
            ('\n#include "building_identity_census.inc"\n', ''),
        )
        if '#include "building_identity_census.inc"' in source:
            for added,prior in owner_delta:
                expected=2 if added.startswith('BindingDetails') else 1
                assert source.count(added)==expected, 'Building-only census exact additive boundary differs'
                source=source.replace(added,prior)
    if relative=='src/game/object_identity/remove_runtime/copy/world_prop_reader.cpp':
        added='    bool reused=false;\n    if(!RootSceneryReadBatch::reuse_world(out,idle,image_,thread_,api_,reused,e))return false;\n    if(reused)return true;\n'
        ready='        if(batch)batch->world_ready=true;\n'
        assert source.count(added)==1 and source.count(ready)==1, 'Saved Root complete World context admission differs'
        source=source.replace(added,'',1).replace(ready,'',1)
    if relative=='src/game/object_identity/remove_runtime/copy/world_prop_reader.cpp':
        for added,prior in LEAF_DELTAS:
            assert source.count(added)==1, 'Pure World/saved Scenery field boundary differs'
            source=source.replace(added,prior,1)
    if relative=='src/game/remove_diagnostics.cpp':
        routed='if(!host::RootSceneryReadBatch::read_current(world,error))return false;'
        prior='if(!native_open_runtime::read_current_world(world,error))return false;'
        assert source.count(routed)==1, 'Saved Root Origin exact routing boundary differs'
        source=source.replace(routed,prior,1)
    for added, prior in DELTAS.get(relative, []):
        assert source.count(added)==1, 'Saved Root batch exact additive boundary differs: '+relative
        source=source.replace(added,prior,1)
    return source

def verify(root):
    for relative,digest in PINS.items():
        assert hashlib.sha256((root/relative).read_bytes()).hexdigest()==digest, 'Saved Root batch core/native boundary differs: '+relative
